css:
.alliancesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2436;
    background: linear-gradient(165deg, #f4f1ea 0%, #eae6db 100%);
    border-radius: 18px;
}

.alliancesim-container * {
    box-sizing: border-box;
}

.alliancesim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #10182c 0%, #1c2a4a 55%, #2a3c63 100%);
    color: #f6f3ea;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(16, 24, 44, 0.34);
    border-bottom: 3px solid #c8a24a;
}

.alliancesim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.alliancesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e7d3a0;
    background: rgba(200, 162, 74, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(200, 162, 74, 0.32);
}

.alliancesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.58;
    color: #d8dbe6;
}

.alliancesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3a5c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.alliancesim-period-counter #currentDay,
.alliancesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #10182c;
}

.alliancesim-round-name {
    background: #1c2a4a;
    color: #e7d3a0;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.alliancesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a14;
    background: #f3e6c6;
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid #e3cf95;
}

.alliancesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.alliancesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd6c6;
    box-shadow: 0 4px 14px rgba(16, 24, 44, 0.07);
    border-top: 4px solid #2a3c63;
}

.alliancesim-card-value { border-top-color: #1f7a52; }
.alliancesim-card-control { border-top-color: #2a3c63; }
.alliancesim-card-trust { border-top-color: #c8a24a; }
.alliancesim-card-ip { border-top-color: #7a4fa0; }

.alliancesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7280;
}

.alliancesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #10182c;
}

.alliancesim-card-value .alliancesim-value { color: #1f7a52; }
.alliancesim-card-control .alliancesim-value { color: #2a3c63; }
.alliancesim-card-trust .alliancesim-value { color: #a8842f; }
.alliancesim-card-ip .alliancesim-value { color: #7a4fa0; }

.alliancesim-sublabel {
    font-size: 0.76rem;
    color: #7a8190;
    line-height: 1.35;
}

.alliancesim-trust-low .alliancesim-value { color: #c0392b; }
.alliancesim-trust-low { border-top-color: #c0392b; }

.alliancesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #10182c;
    color: #eef0f6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.alliancesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7d3a0;
}

.alliancesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c8a24a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(16, 24, 44, 0.06);
}

.alliancesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.alliancesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #10182c;
    margin-bottom: 6px;
}

.alliancesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #36405a;
}

.alliancesim-briefing-text strong { color: #1f7a52; }
.alliancesim-briefing-text em { color: #8a5a14; font-style: italic; }

.alliancesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd6c6;
    box-shadow: 0 4px 14px rgba(16, 24, 44, 0.07);
}

.alliancesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #10182c;
    border-bottom: 2px solid #ece6d7;
    padding-bottom: 8px;
}

.alliancesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243150;
    margin: 14px 0 6px;
}

.alliancesim-container select,
.alliancesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbc1a8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f3;
    color: #1b2436;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.alliancesim-container select:focus,
.alliancesim-container input[type="number"]:focus {
    outline: none;
    border-color: #c8a24a;
    box-shadow: 0 0 0 3px rgba(200, 162, 74, 0.20);
}

.alliancesim-container select option {
    background-color: #ffffff;
    color: #1b2436;
}

.alliancesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c8a24a;
}

.alliancesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2a3c63;
    margin-top: 4px;
}

.alliancesim-range-readout span:nth-child(2) {
    color: #1f7a52;
    font-weight: 800;
}

.alliancesim-hint {
    font-size: 0.8rem;
    color: #7a8190;
    margin-top: 4px;
    line-height: 1.45;
    font-style: italic;
}

.alliancesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.alliancesim-container .btn-primary {
    background: linear-gradient(135deg, #1c2a4a 0%, #2a3c63 100%);
    border: none;
    padding: 11px 28px;
    border-radius: 9px;
    color: #f6f3ea;
    box-shadow: 0 6px 16px rgba(28, 42, 74, 0.30);
}

.alliancesim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.alliancesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbc1a8;
    color: #6b7280;
}

.alliancesim-coach {
    background: #10182c;
    color: #eef0f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(16, 24, 44, 0.24);
    border-left: 4px solid #c8a24a;
}

.alliancesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7d3a0;
    margin-bottom: 8px;
}

.alliancesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.alliancesim-coach-body strong { color: #f0d68a; }
.alliancesim-coach-body em { color: #f3c39a; font-style: italic; }

.alliancesim-history,
.alliancesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd6c6;
    box-shadow: 0 4px 14px rgba(16, 24, 44, 0.07);
}

.alliancesim-history h3,
.alliancesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #10182c;
}

.alliancesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243150;
}

.alliancesim-container table#usfHistoryTable th {
    background: #f1ede2;
    color: #10182c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd6c6;
}

.alliancesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efeade;
}

.alliancesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f1;
}

.alliancesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .alliancesim-container {
        padding: 14px;
    }
    .alliancesim-header h1 {
        font-size: 1.7rem;
    }
    .alliancesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .alliancesim-value {
        font-size: 2rem;
    }
    .alliancesim-clock {
        margin-left: 0;
    }
    .alliancesim-period-counter {
        font-size: 0.88rem;
    }
    .alliancesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .alliancesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ===== v1.1.0 completion message (instructor + student debrief) — append-only ===== */
.alliancesim-cm{background:#ffffff;border:1px solid #dfe3ea;border-radius:12px;padding:22px 24px;margin:18px 0;color:#1b2436;font-family:inherit;box-shadow:0 2px 10px rgba(16,24,44,0.06);}
