(function() {
    'use strict';

    class AllianceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Alliance Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.PIE = 300;                  // USD 300M fixed enterprise valuation
            this.START_VALUE = 90;           // Sundara contribution floor (USD M)
            this.MAX_VALUE = 130;            // Sundara contribution cap (USD M)
            this.START_TRUST = 55;           // partner trust index / 100
            this.START_CONTROL = 20;         // real decision rights / 100
            this.START_IP = 10;              // IP protection / 100
            this.CAPITAL_CAP = 60;           // negotiating capital, in points
            this.TARGET_VALUE = 115;         // a fair value-capture trajectory (USD M)
            this.TARGET_CONTROL = 65;        // protected on the decisions that matter
            this.TRUST_FLOOR = 35;           // below this, Voltaic doubts you want a partner

            // Concept truths.
            this.TRUE_INTEREST = `ip`;
            this.TRUE_CRITICAL = `iplicense`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    control: this.START_CONTROL,
                    trust: this.START_TRUST,
                    ip: this.START_IP,
                    capitalUsed: 0,
                    claimedValue: this.START_VALUE,   // R1 contribution claim, converted in R2
                    dealClosed: true,
                    walkRisk: false,
                    overReached: false,
                    valueHistory: [this.START_VALUE],
                    controlHistory: [this.START_CONTROL],
                    trustHistory: [this.START_TRUST],
                    ipHistory: [this.START_IP],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Middling / neutral defaults — NOT the textbook-correct play.
                state.decisions = {
                    interest: `board`,
                    value: 100,
                    critical: `ceo`,
                    equity: `50_50`,
                    reserved: 40,
                    ip: `licenseplain`,
                    deadlock: `casting`,
                    package: `light`,
                    lockin: 3,
                    clawback: `shared`,
                    pacing: 50,
                    shock: `cave`,
                    flex: `reserved`,
                    close: `goquiet`,
                    walkaway: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const it = document.getElementById(`interestInput`);
                const va = document.getElementById(`valueInput`);
                const cr = document.getElementById(`criticalInput`);
                if (it) decisions.interest = it.value;
                if (va) decisions.value = parseInt(va.value, 10);
                if (cr) decisions.critical = cr.value;
                if (!Number.isFinite(decisions.value) || decisions.value < this.START_VALUE || decisions.value > this.MAX_VALUE) {
                    warn(`warn_value_range`); return false;
                }
            } else if (round === 2) {
                const eq = document.getElementById(`equityInput`);
                const re = document.getElementById(`reservedInput`);
                const ip = document.getElementById(`ipInput`);
                const dl = document.getElementById(`deadlockInput`);
                if (eq) decisions.equity = eq.value;
                if (re) decisions.reserved = parseInt(re.value, 10);
                if (ip) decisions.ip = ip.value;
                if (dl) decisions.deadlock = dl.value;
                if (!Number.isFinite(decisions.reserved) || decisions.reserved < 0 || decisions.reserved > 100) {
                    warn(`warn_reserved_range`); return false;
                }
            } else if (round === 3) {
                const pk = document.getElementById(`packageInput`);
                const lk = document.getElementById(`lockinInput`);
                const cb = document.getElementById(`clawbackInput`);
                const pc = document.getElementById(`pacingInput`);
                if (pk) decisions.package = pk.value;
                if (lk) decisions.lockin = parseInt(lk.value, 10);
                if (cb) decisions.clawback = cb.value;
                if (pc) decisions.pacing = parseInt(pc.value, 10);
                if (!Number.isFinite(decisions.lockin) || decisions.lockin < 0 || decisions.lockin > 10) {
                    warn(`warn_lockin_range`); return false;
                }
                if (!Number.isFinite(decisions.pacing) || decisions.pacing < 0 || decisions.pacing > 100) {
                    warn(`warn_pacing_range`); return false;
                }
            } else if (round === 4) {
                const sh = document.getElementById(`shockInput`);
                const fl = document.getElementById(`flexInput`);
                const cl = document.getElementById(`closeInput`);
                const wa = document.getElementById(`walkawayInput`);
                if (sh) decisions.shock = sh.value;
                if (fl) decisions.flex = fl.value;
                if (cl) decisions.close = cl.value;
                if (wa) decisions.walkaway = parseInt(wa.value, 10);
                if (!Number.isFinite(decisions.walkaway) || decisions.walkaway < 0 || decisions.walkaway > 100) {
                    warn(`warn_walkaway_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas applied to the four meters; capital = negotiating capital spent.
            let valueDelta = 0, controlDelta = 0, trustDelta = 0, ipDelta = 0, capital = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map interests vs positions. The real interest behind Voltaic's "majority"
                // demand is protecting its cell IP — see that and you can trade structure for it.
                if (d.interest === this.TRUE_INTEREST) {
                    controlDelta += 8; trustDelta += 4; coachKey = `coach_r1_interest_right`;
                } else if (d.interest === `majority`) {
                    controlDelta -= 6; trustDelta -= 2; coachKey = `coach_r1_majority`;
                } else if (d.interest === `cash`) {
                    controlDelta -= 2; coachKey = `coach_r1_cash`;
                } else {
                    controlDelta += 1; coachKey = `coach_r1_board`;
                }

                // Value your own contribution. The claim is banked and converted in R2.
                ds.claimedValue = d.value;
                if (d.value >= 120) { trustDelta -= 1; coachKey = (d.interest === this.TRUE_INTEREST) ? `coach_r1_fullvalue` : coachKey; }
                else if (d.value <= 95) { coachKey = `coach_r1_underprice`; }

                // The decision where control matters most = IP licensing back to parents (2019).
                if (d.critical === this.TRUE_CRITICAL) {
                    controlDelta += 6; ipDelta += 6;
                    if (d.interest === this.TRUE_INTEREST) coachKey = `coach_r1_diag_sharp`;
                } else if (d.critical === `capex`) {
                    controlDelta += 3;
                } else if (d.critical === `pricing`) {
                    controlDelta += 1; coachKey = `coach_r1_pricing`;
                } else {
                    controlDelta += 2; coachKey = (coachKey === `coach_r1_board`) ? `coach_r1_ceo` : coachKey;
                }

                summaryKey = (d.interest === this.TRUE_INTEREST && d.critical === this.TRUE_CRITICAL) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Architect equity + governance. Equity is NOT control.
                // Value capture: convert the R1 claim through the equity share, with a strategic
                // premium for market access/regulatory that justifies more than book contribution.
                const eqMap = { '51_49': 51, '49_51': 49, '50_50': 50, '45_55': 45, '40_60': 40 };
                const share = eqMap[d.equity] || 50;
                // Value capture = Sundara's % of the $300M pie, discounted if you underpriced your
                // own contribution in R1 (claimed near $90M => you rounded yourself down).
                const valuationFactor = 0.74 + 0.22 * ((ds.claimedValue - this.START_VALUE) / (this.MAX_VALUE - this.START_VALUE));
                ds.value = Math.round(this.PIE * (share / 100) * valuationFactor);
                ds.value = Math.max(this.START_VALUE - 10, Math.min(155, ds.value));

                // Equity tunnel-vision: grabbing 51% costs the governance that confers real control.
                if (d.equity === `51_49`) {
                    controlDelta += 1; trustDelta -= 7; capital += 14; coachKey = `coach_r2_equity51`;
                } else if (d.equity === `49_51`) {
                    controlDelta += 4; trustDelta += 2; capital += 4; coachKey = `coach_r2_minority`;
                } else if (d.equity === `50_50`) {
                    controlDelta += 1; trustDelta += 1; capital += 2; coachKey = `coach_r2_5050`;
                } else if (d.equity === `45_55`) {
                    controlDelta += 0; trustDelta += 3; capital += 1;
                } else {
                    controlDelta -= 5; trustDelta += 4; capital += 0; coachKey = `coach_r2_4060`;
                }

                // Reserved matters: the true source of minority protection — but too many = deadlock.
                if (d.reserved >= 30 && d.reserved <= 55) {
                    controlDelta += 12; trustDelta -= 3; capital += Math.round(d.reserved / 6);
                    coachKey = (d.equity === `49_51`) ? `coach_r2_reserved_sweet` : coachKey;
                } else if (d.reserved > 55) {
                    controlDelta += 7; trustDelta -= 13; capital += Math.round(d.reserved / 5);
                    coachKey = `coach_r2_reserved_heavy`;
                } else if (d.reserved >= 15) {
                    controlDelta += 5; trustDelta -= 1; capital += 2;
                } else {
                    controlDelta -= 4; capital += 0; coachKey = `coach_r2_reserved_thin`;
                }

                // IP ring-fencing: license-in + clawback closes the 2019 wound structurally.
                if (d.ip === `licensein`) {
                    ipDelta += 28; controlDelta += 3; capital += 4;
                    if (d.reserved >= 30 && d.reserved <= 55) coachKey = `coach_r2_ringfence`;
                } else if (d.ip === `licenseplain`) {
                    ipDelta += 12; capital += 2;
                } else {
                    ipDelta -= 6; trustDelta += 2; coachKey = `coach_r2_transfer`;
                }

                // Deadlock mechanism — essential the more equal the split.
                if (d.deadlock === `escalation`) {
                    controlDelta += 4; trustDelta += 2;
                } else if (d.deadlock === `casting`) {
                    controlDelta += 2;
                } else {
                    controlDelta -= 4;
                    if (d.equity === `50_50`) { controlDelta -= 8; trustDelta += 2; coachKey = `coach_r2_deadlock5050`; }
                }

                summaryKey = (d.reserved >= 30 && d.reserved <= 55 && d.ip === `licensein` && d.equity !== `51_49` && d.equity !== `40_60`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Exit clauses & trust safeguards. Every protective clause spends trust.
                switch (d.package) {
                    case `targeted`: controlDelta += 8; ipDelta += 8; trustDelta -= 6; capital += 12; coachKey = `coach_r3_targeted`; break;
                    case `stacked`: controlDelta += 11; ipDelta += 10; trustDelta -= 30; capital += 30; ds.overReached = true; coachKey = `coach_r3_stacked`; break;
                    case `light`: controlDelta += 3; ipDelta -= 2; trustDelta += 4; capital += 3; coachKey = `coach_r3_light`; break;
                }

                // Lock-in: 3-5y is the sweet spot; 0 invites flight; 7+ reads as distrust.
                if (d.lockin >= 3 && d.lockin <= 5) {
                    controlDelta += 5; trustDelta += 1; capital += 3;
                } else if (d.lockin > 5) {
                    controlDelta += 2; trustDelta -= 8; capital += d.lockin; coachKey = `coach_r3_longlock`;
                } else {
                    controlDelta -= 4; trustDelta += 2; coachKey = `coach_r3_nolock`;
                }

                // IP on exit: clawback + non-compete is the structural close to 2019.
                if (d.clawback === `clawback`) {
                    ipDelta += 22; controlDelta += 2; trustDelta -= 4; capital += 6;
                    if (d.package === `targeted`) coachKey = `coach_r3_clawback`;
                } else if (d.clawback === `shared`) {
                    ipDelta -= 14; trustDelta += 3; coachKey = `coach_r3_sharedip`;
                } else {
                    ipDelta -= 6; coachKey = `coach_r3_nothingip`;
                }

                // Trust-pacing: careful sequencing recovers some of the trust your demands spend.
                if (d.pacing >= 70) { trustDelta += 12; }
                else if (d.pacing >= 45) { trustDelta += 6; }
                else if (d.pacing <= 20) { trustDelta -= 6; coachKey = `coach_r3_nopacing`; }

                summaryKey = (d.package === `targeted` && d.clawback === `clawback` && d.lockin >= 3 && d.lockin <= 5) ? `sum_r3_good` : (d.package === `stacked` ? `sum_r3_over` : `sum_r3_weak`);
            } else if (round === 4) {
                // Close under the day-50 shock. Price the concession against the walk-away.
                switch (d.shock) {
                    case `quantify`: valueDelta += 6; controlDelta += 4; trustDelta += 6; coachKey = `coach_r4_quantify`; break;
                    case `cave`: valueDelta -= 22; trustDelta += 4; controlDelta -= 8; coachKey = `coach_r4_cave`; break;
                    case `holdall`: valueDelta += 2; trustDelta -= 18; ds.walkRisk = true; coachKey = `coach_r4_holdall`; break;
                }

                // What to flex: protect the IP ring-fence + reserved matters; flex a time-limited royalty.
                switch (d.flex) {
                    case `royalty`: controlDelta += 4; ipDelta += 4; trustDelta += 3; coachKey = (d.shock === `quantify`) ? `coach_r4_flexroyalty` : coachKey; break;
                    case `reserved`: controlDelta -= 18; trustDelta += 2; coachKey = `coach_r4_flexreserved`; break;
                    case `ip`: ipDelta -= 24; controlDelta -= 6; trustDelta += 4; coachKey = `coach_r4_flexip`; break;
                }

                // The close to Voltaic's board.
                switch (d.close) {
                    case `gohonest`: valueDelta += 6; controlDelta += 4; trustDelta += 4; coachKey = (d.shock === `quantify` && d.flex === `royalty`) ? `coach_r4_gohonest` : coachKey; break;
                    case `goquiet`: valueDelta += 2; trustDelta += 1; break;
                    case `hold`: trustDelta -= 14; ds.walkRisk = true; coachKey = `coach_r4_hold`; break;
                }

                // Walk-away discipline nudges value capture (a priced BATNA wins concessions).
                valueDelta += Math.round((d.walkaway - 50) / 10);
                if (d.walkaway >= 70 && d.shock === `quantify`) controlDelta += 2;

                summaryKey = (d.shock === `quantify` && d.flex === `royalty` && d.close === `gohonest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.capitalUsed = Math.max(0, Math.round(ds.capitalUsed + capital));

            // Apply deltas, clamped 0-100 (value is in $M, clamped to a sensible band).
            ds.control = Math.max(0, Math.min(100, ds.control + controlDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.ip = Math.max(0, Math.min(100, ds.ip + ipDelta));
            ds.value = Math.max(this.START_VALUE - 10, Math.min(155, ds.value + valueDelta));

            // Overspending negotiating capital binds: it costs trust and risks the walk.
            if (ds.capitalUsed > this.CAPITAL_CAP) {
                const over = ds.capitalUsed - this.CAPITAL_CAP;
                ds.trust = Math.max(0, ds.trust - Math.min(14, over));
                ds.overReached = true;
            }

            // A collapsed trust index means Voltaic doubts you want a partner — the deal can fail.
            if (round === this.ROUNDS.length) {
                if (ds.trust < this.TRUST_FLOOR || ds.walkRisk) ds.dealClosed = false;
                else ds.dealClosed = true;
            }

            ds.valueHistory.push(Math.round(ds.value));
            ds.controlHistory.push(Math.round(ds.control));
            ds.trustHistory.push(Math.round(ds.trust));
            ds.ipHistory.push(Math.round(ds.ip));

            // v1.1.0 fix: persist the instructor-card composite EVERY period.
            // Grading/reporting layer reads domainState.performance.overallScore.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                control: Math.round(ds.control),
                controlDelta: Math.round(controlDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                ip: Math.round(ds.ip),
                ipDelta: Math.round(ipDelta),
                capitalUsed: ds.capitalUsed,
                dealClosed: ds.dealClosed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

