        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.controlHistory.map((_, i) => (i === 0 ? this._cl(`chart_start`) : this._cl(`chart_round_prefix`) + i));
            return {
                allianceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.controlHistory },
                        { data: ds.trustHistory },
                        { data: ds.ipHistory }
                    ]
                }
            };
