        _composite(ds) {
            const value = Math.round(ds.value);
            const control = Math.round(ds.control);
            const trust = Math.round(ds.trust);
            const ip = Math.round(ds.ip);
            // Composite: control 0.32, trust 0.26, ip 0.24, value (scaled to /150) 0.18.
            return Math.round(control * 0.32 + trust * 0.26 + ip * 0.24 + Math.min(100, (value / 150) * 100) * 0.18);
        }

        _cl(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const control = Math.round(ds.control);
            const trust = Math.round(ds.trust);
            const ip = Math.round(ds.ip);

            const closed = ds.dealClosed && trust >= this.TRUST_FLOOR;
            const protectedWell = control >= this.TARGET_CONTROL && ip >= 60;
            const goodValue = value >= this.TARGET_VALUE;
            const composite = this._composite(ds);

            let performanceKey = `grade_collapsed`;
            if (closed && protectedWell && goodValue && composite >= 70) performanceKey = `grade_master`;
            else if (closed && protectedWell && composite >= 58) performanceKey = `grade_well`;
            else if (closed && composite >= 48) performanceKey = `grade_thin`;
            else if (closed) performanceKey = `grade_exposed`;
            else if (!ds.dealClosed) performanceKey = `grade_walked`;
            const performance = window.mySimulation.t(performanceKey);
            const met = closed && composite >= 58;

            const insights = [];
            if (closed && protectedWell && goodValue) insights.push(window.mySimulation.t(`insight_master`));
            else if (!ds.dealClosed) insights.push(window.mySimulation.t(`insight_walked`));
            else if (closed && !protectedWell) insights.push(window.mySimulation.t(`insight_exposed`));
            else insights.push(window.mySimulation.t(`insight_thin`));

            if (ip < 50) insights.push(window.mySimulation.t(`insight_ipweak`));
            if (control < 45) insights.push(window.mySimulation.t(`insight_controlweak`));
            if (trust < this.TRUST_FLOOR) insights.push(window.mySimulation.t(`insight_trustgone`));
            if (ds.overReached) insights.push(window.mySimulation.t(`insight_overreach`));
            if (closed && protectedWell && trust >= 50) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                value: value,
                control: control,
                trust: trust,
                ip: ip,
                closed: closed,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                overReached: !!ds.overReached,
                walkRisk: !!ds.walkRisk,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="alliancesim-cm-badge ` + (s.met ? `alliancesim-cm-met` : `alliancesim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (!s.closed) badges.push(`<span class="alliancesim-cm-badge alliancesim-cm-fail">` + t(`cm_fail_walked`) + `</span>`);
            if (s.overReached) badges.push(`<span class="alliancesim-cm-badge alliancesim-cm-fail">` + t(`cm_fail_overreach`) + `</span>`);
            const kpi = (label, val) => `<div class="alliancesim-cm-metric"><div class="alliancesim-cm-metric-val">` + val + `</div><div class="alliancesim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_value`), `$` + (s.value != null ? s.value : 0) + `M`) + kpi(t(`cm_control`), (s.control != null ? s.control : 0)) + kpi(t(`cm_trust`), (s.trust != null ? s.trust : 0)) + kpi(t(`cm_ip`), (s.ip != null ? s.ip : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="alliancesim-cm">`
                + `<div class="alliancesim-cm-head"><div class="alliancesim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="alliancesim-cm-scorewrap"><span class="alliancesim-cm-score">` + score + `</span><span class="alliancesim-cm-score-max">/100</span></div>`
                + `<div class="alliancesim-cm-grade">` + grade + `</div>`
                + `<div class="alliancesim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="alliancesim-cm-metrics">` + kpis + `</div>`
                + `<div class="alliancesim-cm-insights"><div class="alliancesim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.trust < this.TRUST_FLOOR) return window.mySimulation.t(`hint_trust`);
            if (ds.overReached && state.currentPeriod >= 3) return window.mySimulation.t(`hint_overreach`);
            if (ds.ip < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_ip`);
            if (ds.control < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_control`);
            if (ds.control >= this.TARGET_CONTROL && ds.ip >= 60 && ds.trust >= 45) return window.mySimulation.t(`hint_strong`);
            return null;
        }

